import 'package:flutter/material.dart';

class ClickCounterButton extends StatefulWidget {
  final String buttonLabel;
  final int initialCount;

  const ClickCounterButton({
    Key? key,
    required this.buttonLabel,
    this.initialCount = 0,
  }) : super(key: key);

  @override
  _ClickCounterButtonState createState() => _ClickCounterButtonState();
}

class _ClickCounterButtonState extends State<ClickCounterButton> {
  late int _currentCount;

  @override
  void initState() {
    super.initState();
    _currentCount = widget.initialCount;
  }

  void _incrementCounter() {
    setState(() {
      _currentCount++;
    });
  }

  @override
  Widget build(BuildContext context) {
    return ElevatedButton(
      onPressed: _incrementCounter,
      child: Text('${widget.buttonLabel}: $_currentCount'),
    );
  }
}
